ALLOWED={'scripts/production/release-batch.py', 'contracts/production/shared-release-authority.v1.bundle', 'scripts/production/validate-order4-release.py', 'contracts/production/authority-successors/order5-batch3-predecessor-profile.v1.json', 'scripts/production/order5-batch3-scope.py', 'contracts/production/release-profiles/order5-batch3-thermosl.v1.json', 'contracts/production/order5-batch3-assets/apw431.json', '.github/workflows/common-release-contract.yml', 'contracts/production/current-authority-successor.json', 'contracts/production/shared-release-authority.v1.json', 'scripts/production/validate-order5-release.py', 'src/catalog/runtime-master-packages/ykkap-apw431-v1.2/runtime_manifest.json', 'contracts/production/authority-successors/order5-batch3.v1.json', 'scripts/production/release-contract.py', 'contracts/production/release-profiles/order5-batch3-apw431.v1.json', 'contracts/production/authority-successors/order5-batch3-predecessor-selection.v1.json', 'contracts/production/release-profile.v1.json', 'contracts/production/order5-batch3-scope.v1.json', 'contracts/production/release-profiles/order5-batch3-tw.v1.json', 'contracts/production/order5-batch3-assets/thermosl.json', 'contracts/production/release-profiles/order5-batch3-apw430.v1.json', 'contracts/production/release-profiles.v1.json', 'contracts/production/order5-batch3-assets/tw.json', 'contracts/production/order5-batch3-assets/apw430.json', 'scripts/production/test_order5_batch3_scope.py', 'docs/ORDER5_BATCH3.md'}
